package com.hs.jxc.inv.service;
import com.hs.jxc.common.api.*;
import com.hs.jxc.common.context.RequestContext;
import com.hs.jxc.common.db.DbRows;
import com.hs.jxc.sal.api.SalesStatsApi;
import com.hs.jxc.sys.api.*;
import com.hs.jxc.sys.service.AuthorizationService;
import java.math.BigDecimal;
import java.time.*;
import java.time.temporal.TemporalAdjusters;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
@Service
public class InventoryClassification {
 private final com.hs.jxc.sys.service.CountryCalendar calendar;private final com.hs.jxc.lgs.api.LogisticsApi logistics;private final JdbcTemplate jdbc;private final AuthorizationService auth;private final JsonCodec json;private final SalesStatsApi sales;private final TransactionTemplate tx;
 public InventoryClassification(com.hs.jxc.sys.service.CountryCalendar calendar,com.hs.jxc.lgs.api.LogisticsApi logistics,JdbcTemplate jdbc,AuthorizationService auth,JsonCodec json,SalesStatsApi sales,PlatformTransactionManager tm){this.calendar=calendar;this.logistics=logistics;this.jdbc=jdbc;this.auth=auth;this.json=json;this.sales=sales;this.tx=new TransactionTemplate(tm);}
 @SuppressWarnings("unchecked") private List<Map<String,Object>> conditions(Object o){if(o instanceof String text)return (List<Map<String,Object>>)(List<?>)json.readMap("{\"items\":"+text+"}").get("items");if(o instanceof List<?> list)return (List<Map<String,Object>>)(List<?>)list;throw Inputs.bad("请配置联合条件");}
 private BigDecimal decimal(Map<String,Object> r,String key){Object v=r.get(key);if(v==null)return BigDecimal.ZERO;return Inputs.decimal(v,4,new BigDecimal("999999999999"));}
 private record Range(BigDecimal low,boolean lowClosed,BigDecimal high,boolean highClosed){boolean contains(BigDecimal n){return (low==null||n.compareTo(low)>0||lowClosed&&n.compareTo(low)==0)&&(high==null||n.compareTo(high)<0||highClosed&&n.compareTo(high)==0);}boolean overlaps(Range b){if(high!=null&&b.low!=null&&(high.compareTo(b.low)<0||high.compareTo(b.low)==0&&!(highClosed&&b.lowClosed)))return false;if(b.high!=null&&low!=null&&(b.high.compareTo(low)<0||b.high.compareTo(low)==0&&!(b.highClosed&&lowClosed)))return false;return true;}}
 private Range range(Map<String,Object> c,String prefix){String op=Objects.toString(c.get(prefix+"Op"),"ANY");var n=decimal(c,prefix+"Value");return switch(op){case "ANY"->new Range(null,false,null,false);case "LT"->new Range(null,false,n,false);case "LTE"->new Range(null,false,n,true);case "GT"->new Range(n,false,null,false);case "GTE"->new Range(n,true,null,false);case "BETWEEN"->{var end=decimal(c,prefix+"Value2");if(end.compareTo(n)<0)throw Inputs.bad("区间上限不能低于下限");yield new Range(n,true,end,true);}default->throw Inputs.bad("条件运算符不合法");};}
 public Object rules(RequestContext c){return tx.execute(s->{var a=auth.authorize(c);a.require("inv:classify:view","inv:classify:config");return Map.of("records",rules(a),"total",rules(a).size());});}
 private List<Map<String,Object>> rules(Access a){return jdbc.queryForList("SELECT * FROM inv_classify_rule WHERE country_id=? ORDER BY id DESC",a.requireCountry()).stream().map(DbRows::camel).map(r->{r.put("conditions",conditions(r.get("conditions").toString()));return r;}).toList();}
 public List<Map<String,Object>> validateConditions(Object value){var cond=conditions(value);for(var x:cond){if(Inputs.id(x.get("priority"))>100000||!Inputs.required(x,"label").matches("[A-Z0-9_]{1,64}"))throw Inputs.bad("条件标签或优先级不合法");range(x,"stock");range(x,"order");}for(int i=0;i<cond.size();i++)for(int j=i+1;j<cond.size();j++){var x=cond.get(i);var y=cond.get(j);if(Inputs.id(x.get("priority"))==Inputs.id(y.get("priority"))&&!x.get("label").equals(y.get("label"))&&range(x,"stock").overlaps(range(y,"stock"))&&range(x,"order").overlaps(range(y,"order")))throw new ApiException(409,"INV_RULE_CONFLICT","同优先级库存及订单区间重叠: 条件"+(i+1)+"与"+(j+1));}return cond;}
 public Object save(RequestContext c,Long oldId,Map<String,Object> b){return tx.execute(s->{var a=auth.authorize(c);a.require("inv:classify:config");var cond=validateConditions(b.get("conditions"));
  String dim=Inputs.text(b,"dimType","WAREHOUSE"),period=Inputs.text(b,"periodType","ROLLING_DAYS"),order=Inputs.text(b,"orderMetric","QTY"),stock=Inputs.text(b,"stockMetric","AVAILABLE");if(!Set.of("COUNTRY","WAREHOUSE","STORE").contains(dim)||!Set.of("ROLLING_DAYS","CALENDAR_MONTH","CALENDAR_WEEK").contains(period)||!Set.of("QTY","ORDER_COUNT").contains(order)||!Set.of("AVAILABLE","ON_HAND").contains(stock))throw Inputs.bad("规则指标不合法");long days=b.get("periodDays")==null?90:Inputs.id(b.get("periodDays"));if(days>3650)throw Inputs.bad("统计天数过大");int version=1;if(oldId!=null){var prev=rule(a,oldId,true);if(!"ACTIVE".equals(prev.get("status"))||b.get("versionNo")==null||Inputs.id(b.get("versionNo"))!=((Number)prev.get("version_no")).longValue())throw Inputs.conflict();version=((Number)prev.get("version_no")).intValue()+1;jdbc.update("UPDATE inv_classify_rule SET status='RETIRED' WHERE country_id=? AND id=?",a.requireCountry(),oldId);}long id=jdbc.queryForObject("INSERT INTO inv_classify_rule(country_id,name,dim_type,period_type,period_days,order_metric,stock_metric,version_no,effective_from,conditions,created_by) VALUES(?,?,?,?,?,?,?,?,?,?::jsonb,?) RETURNING id",Long.class,a.requireCountry(),Inputs.required(b,"name"),dim,period,days,order,stock,version,b.get("effectiveFrom")==null?today(a):LocalDate.parse(b.get("effectiveFrom").toString()),json.write(cond),a.userId());if("ACTIVE".equals(jdbc.queryForObject("SELECT status FROM sys_country WHERE id=?",String.class,a.requireCountry())))recalculate(a,id,"RULE",String.valueOf(id));return DbRows.camel(rule(a,id,false));});}
 private LocalDate today(Access a){return today(a.requireCountry());}
 private LocalDate today(long country){return calendar.today(country);}
 private Map<String,Object> rule(Access a,long id,boolean lock){var rows=jdbc.queryForList("SELECT * FROM inv_classify_rule WHERE country_id=? AND id=?"+(lock?" FOR UPDATE":""),a.requireCountry(),id);if(rows.isEmpty())throw ApiException.notFound();return rows.getFirst();}
 public Object recalculate(RequestContext c,long id){return tx.execute(s->{var a=auth.authorize(c);a.require("inv:classify:config");return Map.of("count",recalculate(a,id,"RULE",String.valueOf(id)));});}
 public int recalculate(Access a,long id,String trigger,String ref){return compute(a,a.requireCountry(),id,trigger,ref);}
 private int compute(Access a,long country,long id,String trigger,String ref){var scope=a==null?new DataScope(true,Set.of(),Set.of(),Set.of(),Set.of()):a.scope();var rows=jdbc.queryForList("SELECT * FROM inv_classify_rule WHERE country_id=? AND id=? FOR UPDATE",country,id);if(rows.isEmpty())throw ApiException.notFound();var rule=rows.getFirst();if(!"ACTIVE".equals(rule.get("status"))||((java.sql.Date)rule.get("effective_from")).toLocalDate().isAfter(today(country)))return 0;String dim=rule.get("dim_type").toString();var end=today(country);var start=switch(rule.get("period_type").toString()){case "CALENDAR_MONTH"->end.withDayOfMonth(1);case "CALENDAR_WEEK"->end.with(TemporalAdjusters.previousOrSame(DayOfWeek.MONDAY));default->end.minusDays(((Number)rule.get("period_days")).longValue()-1);};
  var cond=conditions(rule.get("conditions").toString()).stream().sorted(Comparator.comparingLong(x->Inputs.id(x.get("priority")))).toList();List<Long> dims=dim.equals("COUNTRY")?List.of(country):jdbc.queryForList("SELECT id FROM "+(dim.equals("STORE")?"org_store":"org_warehouse")+" WHERE country_id=? AND status='ENABLED' ORDER BY id",Long.class,country);int count=0;
  for(long d:dims){if(!scope.all()&&(dim.equals("COUNTRY")||dim.equals("STORE")&&!scope.stores().contains(d)||dim.equals("WAREHOUSE")&&!scope.warehouses().contains(d)))continue;for(long p:jdbc.queryForList("SELECT product_id FROM md_country_sku WHERE country_id=? AND status='ENABLED' ORDER BY product_id",Long.class,country)){
   var stock=jdbc.queryForMap("SELECT coalesce(sum(s.on_hand_qty),0) on_hand_qty,coalesce(sum(s.reserved_qty),0) reserved_qty,coalesce(sum(s.frozen_qty),0) frozen_qty FROM inv_stock_summary s JOIN org_warehouse w ON w.country_id=s.country_id AND w.id=s.warehouse_id WHERE s.country_id=? AND s.product_id=?"+(dim.equals("WAREHOUSE")?" AND w.id=?":dim.equals("STORE")?" AND w.store_id=?":""),dim.equals("COUNTRY")?new Object[]{country,p}:new Object[]{country,p,d});var basis=DbRows.camel(stock);var available=((BigDecimal)stock.get("on_hand_qty")).subtract((BigDecimal)stock.get("reserved_qty")).subtract((BigDecimal)stock.get("frozen_qty"));basis.put("availableQty",available);BigDecimal inTransit=BigDecimal.ZERO;for(long warehouse:jdbc.queryForList("SELECT id FROM org_warehouse WHERE country_id=?"+(dim.equals("WAREHOUSE")?" AND id=?":dim.equals("STORE")?" AND store_id=?":""),Long.class,dim.equals("COUNTRY")?new Object[]{country}:new Object[]{country,d})){var transit=a==null?logistics.projectionTransit(country,warehouse,p):logistics.transit(a,warehouse,p);inTransit=inTransit.add(transit.intlQty()).add(transit.pendingDeliveryQty()).add(transit.onHoldQty()).add(transit.deliveringQty());}basis.put("inTransitQty",inTransit);var orders=a==null?sales.projectionOrders(country,dim,d,p,start,end):sales.orders(a,dim,d,p,start,end);var qty=orders.stream().map(o->(BigDecimal)o.get("qty")).reduce(BigDecimal.ZERO,BigDecimal::add);basis.put("orderQty",qty);basis.put("orderCount",orders.size());for(String k:List.of("outboundQty","returnedQty","unassignedQty"))basis.put(k,orders.stream().map(o->(BigDecimal)o.get(k)).reduce(BigDecimal.ZERO,BigDecimal::add));basis.put("periodStart",start.toString());basis.put("periodEnd",end.toString());basis.put("stockSnapshotAt",Instant.now().toString());basis.put("ruleVersionNo",rule.get("version_no"));String label="PENDING_JUDGE";Map<String,Object> hit=Map.of();for(var x:cond)if(range(x,"stock").contains((BigDecimal)basis.get(rule.get("stock_metric").equals("ON_HAND")?"onHandQty":"availableQty"))&&range(x,"order").contains(rule.get("order_metric").equals("ORDER_COUNT")?BigDecimal.valueOf(orders.size()):qty)){label=x.get("label").toString();hit=x;break;}basis.put("hitCondition",hit);basis.put("hitText",hit.isEmpty()?"没有命中联合条件":json.write(hit));var old=jdbc.queryForList("SELECT id,label,basis,orders FROM inv_classify_result WHERE country_id=? AND rule_id=? AND rule_version_no=? AND dim_type=? AND dim_id=? AND product_id=? FOR UPDATE",country,id,rule.get("version_no"),dim,d,p);long rid=jdbc.queryForObject("INSERT INTO inv_classify_result(country_id,rule_id,rule_version_no,dim_type,dim_id,warehouse_id,store_id,product_id,period_start,period_end,label,basis,orders) VALUES(?,?,?,?,?,?,?,?,?,?,?,?::jsonb,?::jsonb) ON CONFLICT(country_id,rule_id,rule_version_no,dim_type,dim_id,product_id) DO UPDATE SET period_start=excluded.period_start,period_end=excluded.period_end,label=excluded.label,basis=excluded.basis,orders=excluded.orders,computed_at=clock_timestamp() RETURNING id",Long.class,country,id,rule.get("version_no"),dim,d,dim.equals("WAREHOUSE")?d:null,dim.equals("STORE")?d:null,p,start,end,label,json.write(basis),json.write(orders));if(old.isEmpty()||!label.equals(old.getFirst().get("label"))||!sameBasis(old.getFirst().get("basis").toString(),basis)||!json.write(com.hs.jxc.common.idempotency.IdempotencyExecutor.canonical(json.read(old.getFirst().get("orders").toString(),List.class))).equals(json.write(com.hs.jxc.common.idempotency.IdempotencyExecutor.canonical(orders))))jdbc.update("INSERT INTO inv_classify_result_log(country_id,result_id,old_label,new_label,trigger,trigger_ref,basis) VALUES(?,?,?,?,?,?,?::jsonb)",country,rid,old.isEmpty()?null:old.getFirst().get("label"),label,trigger,ref,json.write(basis));count++;
  }}return count;
 }
 private boolean sameBasis(String previous,Map<String,Object> current){var old=json.readMap(previous);var now=new LinkedHashMap<String,Object>(current);old.remove("stockSnapshotAt");now.remove("stockSnapshotAt");return json.write(com.hs.jxc.common.idempotency.IdempotencyExecutor.canonical(old)).equals(json.write(com.hs.jxc.common.idempotency.IdempotencyExecutor.canonical(now)));}
 public void all(Access a,String trigger,String ref){for(long id:jdbc.queryForList("SELECT id FROM inv_classify_rule WHERE country_id=? AND status='ACTIVE' ORDER BY id",Long.class,a.requireCountry()))recalculate(a,id,trigger,ref);}
 public void projectCountry(long country,String trigger,String ref){for(long id:jdbc.queryForList("SELECT id FROM inv_classify_rule WHERE country_id=? AND status='ACTIVE' ORDER BY id",Long.class,country))compute(null,country,id,trigger,ref);}
 public Object results(RequestContext c,Map<String,String> q){return tx.execute(s->{var a=auth.authorize(c);a.require("inv:classify:view","inv:classify:config","inv:stock:view");var out=new ArrayList<Map<String,Object>>();for(var raw:jdbc.queryForList("SELECT r.*,p.product_code,p.name product_name,coalesce(w.name,st.name,ct.name) dim_name FROM inv_classify_result r JOIN md_product p ON p.id=r.product_id JOIN inv_classify_rule rule ON rule.country_id=r.country_id AND rule.id=r.rule_id JOIN sys_country ct ON ct.id=r.country_id LEFT JOIN org_warehouse w ON w.country_id=r.country_id AND w.id=r.warehouse_id LEFT JOIN org_store st ON st.country_id=r.country_id AND st.id=r.store_id WHERE r.country_id=? AND rule.status='ACTIVE' ORDER BY r.id",a.requireCountry())){var r=DbRows.camel(raw);if(!visible(a,r))continue;if(q.containsKey("label")&&!q.get("label").equals(r.get("label")))continue;if(q.containsKey("productId")&&Inputs.id(Long.parseLong(q.get("productId")))!=Inputs.id(r.get("productId")))continue;r.putAll(json.readMap(r.remove("basis").toString()));r.remove("orders");out.add(r);}return Map.of("records",out,"total",out.size());});}
 private boolean visible(Access a,Map<String,Object> r){return a.scope().all()||r.get("warehouseId") instanceof Number w&&a.scope().warehouses().contains(w.longValue())||r.get("storeId") instanceof Number st&&a.scope().stores().contains(st.longValue());}
 public Object orders(RequestContext c,long id){return tx.execute(s->{var a=auth.authorize(c);a.require("inv:classify:view","inv:stock:view");var rows=jdbc.queryForList("SELECT * FROM inv_classify_result WHERE country_id=? AND id=?",a.requireCountry(),id);if(rows.isEmpty()||!visible(a,DbRows.camel(rows.getFirst())))throw ApiException.notFound();return conditions(rows.getFirst().get("orders").toString());});}
}
